#!/bin/bash
# Canli veritabani YEDEGINI gecici bir veritabanina yukleyip yeni kodun ensureDbSchema()'sini orada iki kez calistirir (canli DB'ye dokunmaz).
# 035/036 (platform hizmetleri, hesap silme), 038-041 (toplu yukleme, belgeler, finans 4b, push), 044-046 (anket, ziyaretci, kartli gecis), 047-048 (is takibi fotograf, rezervasyon okunmamis), 049-051 ve 052-078
# (her migration icin o migration'in olusturdugu nesne: tablo / sutun / indeks / kisit / tetikleyici / islev) varlik kontrolleri + IDEMPOTANS:
# ensureDbSchema turlarinda node CIKIS KODU ve "ENSURE_OK tur N" satiri ZORUNLUDUR; yoksa (migration/sema coktuyse) PROVA_SORUNLU basar.
# ikinci ensureDbSchema turundan sonra TUM public semasinin parmak izi (kolon, kisit, indeks, tetikleyici, islev) ilk turla AYNI olmali.
# 085, 088-091, 096-100, 102, 103, 110, 111 (okNNN, ok085-111 grubu): her migration'in nesneleri (tablo / sutun / indeks / kisit / tetikleyici / islev) varlik + (088 / 090) kisitlarin DOGRULANMIS olmasi;
# ayrica yukseltme bu migration'larin tablolarina satir ekler / silerse once/sonra sayim parmak izi (ok085data) uyusmaz ve PROVA_SORUNLU basar.
# Kullanim: bash remote_rehearse_schema.sh <TS>   (once remote_deploy.sh <TS> prepare calismis olmali)
set -u
TS="$1"
DBC=site_kapi_kontrol_postgres
RDB="kapi_rehearsal_${TS}"
STAGE="$HOME/kapi_stage_$TS"
BK="$HOME/backups/kapi_$TS"
ENVF="${KAPI_ENV_FILE:-/var/www/site_kapi_kontrol/server/.env}"
PSQL="docker exec -i $DBC psql -U postgres"

cleanup() { $PSQL -qc "DROP DATABASE IF EXISTS \"$RDB\"" >/dev/null 2>&1; }
trap cleanup EXIT

[ -d "$STAGE/node_modules" ] || { echo "HATA: hazirlik yok"; exit 2; }
echo "[1/5] gecici veritabani: $RDB"
$PSQL -qc "CREATE DATABASE \"$RDB\"" || exit 3
echo "[2/5] yedek yukleniyor"
gunzip -c "$BK/db.sql.gz" | $PSQL -d "$RDB" -q -v ON_ERROR_STOP=0 >/dev/null 2>"$HOME/rehearse_restore_$TS.err"
echo "   yukleme uyarilari (ilk 3): $(head -n 3 "$HOME/rehearse_restore_$TS.err" | cut -c1-120 | tr '\n' '|')"
before_sites=$($PSQL -d "$RDB" -Atc "select count(*) from sites")
before_users=$($PSQL -d "$RDB" -Atc "select count(*) from users")
before_doors=$($PSQL -d "$RDB" -Atc "select count(*) from site_doors")
before_sm=$($PSQL -d "$RDB" -Atc "select count(*) from site_memberships")
before_am=$($PSQL -d "$RDB" -Atc "select count(*) from apartment_memberships where is_active")
before_pps=$($PSQL -d "$RDB" -Atc "select count(*) from payment_provider_settings" 2>/dev/null); before_pps=${before_pps:-0}
# 083 / 084: kataloktan kalkan eski kodlu modul satirlari (card_payments, documents) SILINMEZ (katalog yok sayar; dagitim otomatik geri alinirsa onceki surum bu satirlari okur): once/sonra sayilari esit olmali.
before_cp_sm=$($PSQL -d "$RDB" -Atc "select count(*) from site_modules where module_code = 'card_payments'" 2>/dev/null); before_cp_sm=${before_cp_sm:-0}
before_doc_sm=$($PSQL -d "$RDB" -Atc "select count(*) from site_modules where module_code = 'documents'" 2>/dev/null); before_doc_sm=${before_doc_sm:-0}
# 104 (coklu malik): yukseltme malik satirlarini ne ekler ne siler; once/sonra guncel malik satiri sayisi esit olmali.
before_owners=$($PSQL -d "$RDB" -Atc "select count(*) from apartment_residencies where is_current and relation = 'owner'" 2>/dev/null); before_owners=${before_owners:-0}
# 085-111 (ekleyici migration'lar) once/sonra veri parmak izi: yukseltme bu migration'larin tablolarina / sutunlarina ne satir ekler ne siler. 100 varsayilan kategorileri
# TOHUMLAMAZ (ilk kullanimda sunucu kodu tohumlar). Tablo / sutun yoksa (eski yedek) psql hatasi 0 sayilir; ensureDbSchema bos tablo olusturur, yani yine once = sonra.
cnt() { local v; v=$($PSQL -d "$RDB" -Atc "select count(*) from $1" 2>/dev/null); echo "${v:-0}"; }
snap085() {
  local t s=""
  for t in auth_attempt_limits finance_refunds finance_refund_counters finance_liability_transfers work_categories site_menu_layouts feedback_reports feedback_attachments expense_check_marks payment_notice_check_marks equipment_quotes drive_files fee_runs work_items; do
    s="$s $t=$(cnt "$t")"
  done
  s="$s iade_hareketi=$(cnt "account_movements where kind = 'refund'")"
  s="$s iade_defter=$(cnt "ledger_entries where source_kind in ('refund', 'liability_transfer')")"
  s="$s teklif_revizyon=$(cnt "equipment_quotes where revision_no > 1")"
  s="$s dosya_kaynakli=$(cnt "drive_files where source_type is not null")"
  s="$s tahakkuk_dayanakli=$(cnt "fee_runs where decision_id is not null")"
  s="$s is_ekipmanli=$(cnt "work_items where equipment_id is not null")"
  s="$s is_firmali=$(cnt "work_items where vendor_name is not null")"
  s="$s is_firmada=$(cnt "work_items where status = 'firmada'")"
  echo "${s# }"
}
SNAP085_BEFORE="$(snap085)"
echo "   once: sites=$before_sites users=$before_users doors=$before_doors site_memberships=$before_sm"
echo "[3/5] yeni ensureDbSchema (2 kez, ikinci tur no-op olmali)"
# Sema parmak izi: tum public semasi (kolonlar+varsayilanlar, kisitlar, indeksler, tetikleyiciler, islev govdeleri). Satir SAYILARI dahil degildir.
schema_fp() {
  $PSQL -d "$RDB" -Atc "select md5(coalesce(string_agg(x, chr(10) order by x), '')) from (
    select 'col ' || c.table_name || '.' || c.column_name || ' ' || c.data_type || ' ' || coalesce(c.column_default, '') || ' ' || c.is_nullable as x from information_schema.columns c where c.table_schema = 'public'
    union all select 'con ' || conrelid::regclass::text || ' ' || conname || ' ' || pg_get_constraintdef(oid) || ' ' || convalidated::text from pg_constraint where connamespace = 'public'::regnamespace
    union all select 'idx ' || indexname || ' ' || indexdef from pg_indexes where schemaname = 'public'
    union all select 'trg ' || tgrelid::regclass::text || ' ' || tgname || ' ' || tgenabled::text from pg_trigger where not tgisinternal
    union all select 'fn ' || p.proname || ' ' || md5(p.prosrc) from pg_proc p where p.pronamespace = 'public'::regnamespace
  ) s" 2>&1 | head -n 1
}
FP1=""; FP2=""; ENSURE_OK_ALL=t
cd "$STAGE" || exit 4
export $(grep -E '^(DB_HOST|DB_PORT|DB_USER|DB_PASSWORD)=' "$ENVF" | xargs)
export DB_NAME="$RDB"
for i in 1 2; do
  # Boru (| tail) node'un cikis kodunu yutardi: ciktiyi degiskene al, kodu ve ENSURE_OK satirini AYRI denetle.
  ensure_out=$(node --input-type=module -e "const m = await import('./src/db.js'); await m.ensureDbSchema(); console.log('ENSURE_OK tur $i'); process.exit(0)" 2>&1); ensure_rc=$?
  printf '%s\n' "$ensure_out" | cut -c1-220 | tail -n 6
  if [ "$ensure_rc" -ne 0 ] || ! printf '%s\n' "$ensure_out" | grep -qx "ENSURE_OK tur $i"; then
    ENSURE_OK_ALL=f
    echo "   HATA: ensureDbSchema tur $i BASARISIZ (node cikis kodu=$ensure_rc, 'ENSURE_OK tur $i' satiri $(printf '%s\n' "$ensure_out" | grep -qx "ENSURE_OK tur $i" && echo VAR || echo YOK))"
  fi
  if [ "$i" = 1 ]; then FP1="$(schema_fp)"; else FP2="$(schema_fp)"; fi
done
echo "   ensureDbSchema tur1+tur2: node cikis kodu 0 ve ENSURE_OK satirlari: $([ "$ENSURE_OK_ALL" = t ] && echo TAMAM || echo SORUNLU)"
echo "   sema parmak izi tur1/tur2: ${FP1:0:12} / ${FP2:0:12} ($([ -n "$FP1" ] && [ "$FP1" = "$FP2" ] && echo ESIT-idempotent || echo FARKLI-SORUNLU))"
echo "[4/5] dogrulama"
after_sites=$($PSQL -d "$RDB" -Atc "select count(*) from sites")
after_users=$($PSQL -d "$RDB" -Atc "select count(*) from users")
after_sm=$($PSQL -d "$RDB" -Atc "select count(*) from site_memberships")
after_am=$($PSQL -d "$RDB" -Atc "select count(*) from apartment_memberships where is_active")
after_pps=$($PSQL -d "$RDB" -Atc "select count(*) from payment_provider_settings" 2>/dev/null); after_pps=${after_pps:-0}
after_cp_sm=$($PSQL -d "$RDB" -Atc "select count(*) from site_modules where module_code = 'card_payments'" 2>/dev/null); after_cp_sm=${after_cp_sm:-0}
after_doc_sm=$($PSQL -d "$RDB" -Atc "select count(*) from site_modules where module_code = 'documents'" 2>/dev/null); after_doc_sm=${after_doc_sm:-0}
# Faz 1 (029) her siteye bir yonetim turu yazar; 2026-10-19'dan beri bes tur kullanimda (apartment_site disi da gecerli).
# Kosul: her sitenin taninan bir yonetim turu olmali (eskiden "hepsi apartment_site" bekleniyordu, canlida artik yanlis).
typed=$($PSQL -d "$RDB" -Atc "select count(*) from sites where management_type is not null and management_type <> ''")
typed_apt=$($PSQL -d "$RDB" -Atc "select count(*) from sites where management_type='apartment_site'")
echo "   aktif daire uyeligi once/sonra: $before_am/$after_am"
echo "   sonra: sites=$after_sites (yonetim turu tanimli=$typed, apartment_site=$typed_apt) users=$after_users site_memberships=$after_sm"
echo "   tablolar: $($PSQL -d "$RDB" -Atc "select string_agg(table_name, ',') from information_schema.tables where table_schema='public' and table_name in ('site_modules','audit_log')")"
echo "   site_modules satir: $($PSQL -d "$RDB" -Atc "select count(*) from site_modules") (bilgi: canlida yonetici bir modulu degistirdiyse 0dan buyuk olur)"
q() { $PSQL -d "$RDB" -Atc "$1" 2>&1 | head -n 1; }
echo "   [031] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('site_people','apartment_residencies','vehicles','platform_backfills')")"
echo "   [031] backfill: $(q "select coalesce(string_agg(code, ','), 'YOK') from platform_backfills")"
echo "   [031] tetikleyici: $(q "select count(*) from pg_trigger where tgname='trg_users_preserve_site_people' and not tgisinternal") (1 olmali)"
echo "   [031] kisi=$(q "select count(*) from site_people") (hesapli=$(q "select count(*) from site_people where user_code is not null")) iliski=$(q "select count(*) from apartment_residencies") (guncel=$(q "select count(*) from apartment_residencies where is_current")) origin_sync=$(q "select count(*) from apartment_residencies where origin='sync'") arac=$(q "select count(*) from vehicles")"
echo "   [031] aktif daire uyeligi=$(q "select count(*) from apartment_memberships where is_active") (kapi yetkisi satirlari DEGISMEMELI) toplam=$(q "select count(*) from apartment_memberships")"
echo "   [031] guncel iliski olmayan aktif uyelik (0 olmali): $(q "select count(*) from apartment_memberships am where am.is_active and exists (select 1 from apartments a where a.id=am.apartment_id and a.is_active) and not exists (select 1 from site_people p join apartment_residencies r on r.person_id=p.id and r.is_current where p.user_code=am.user_code and r.apartment_id=am.apartment_id)")"
echo "   [032] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('announcements','announcement_recipients','notification_preferences','announcement_email_suppressions')") (4 olmali)"
echo "   [032] satirlar: duyuru=$(q "select count(*) from announcements") alici=$(q "select count(*) from announcement_recipients") tercih=$(q "select count(*) from notification_preferences") bastirma=$(q "select count(*) from announcement_email_suppressions") (hepsi 0 olmali)"
echo "   [032] sutunlar: $(q "select count(*) from information_schema.columns where table_name in ('announcements','announcement_recipients') and column_name in ('published_by','publish_attempts','next_attempt_at','email_requested_by','email_requested_at','email_hash','email_claimed_at','email_next_at')") (8 olmali)"
echo "   [032] katalog: duyuru modulu eski sayfa/uclar degismedi mi: $(q "select count(*) from site_modules")"
echo "   [033] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('subscription_plans','site_subscriptions','platform_settings','site_applications')") (4 olmali)"
echo "   [034] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('fee_definitions','fee_runs','ledger_entries','finance_period_closures')") (4 olmali)"
echo "   [034] tetikleyici: $(q "select count(*) from pg_trigger where not tgisinternal and (tgname like 'trg_ledger_entries%' or tgname like 'trg_fee_runs%' or tgname like 'trg_finance_%')") (034 tek basina 6; 040 sonrasi 10 olmali: +ledger_entries_late_fee_mirror, +finance_accounts/reminder_runs/settings guard)"
echo "   [034] satirlar: tanim=$(q "select count(*) from fee_definitions") calistirma=$(q "select count(*) from fee_runs") defter=$(q "select count(*) from ledger_entries") kapanis=$(q "select count(*) from finance_period_closures") (hepsi 0 olmali)"
echo "   [034] finans modulu ACIK site (bilgi; 079 ile her sitede acik): $(q "select count(*) from site_modules where module_code='finance' and enabled")"
echo "   [035] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('user_consents','client_error_reports')") (2 olmali)"
echo "   [035] pending_registrations.accepted_documents: $(q "select count(*) from information_schema.columns where table_name='pending_registrations' and column_name='accepted_documents'") (1 olmali)"
echo "   [035] satirlar: onay=$(q "select count(*) from user_consents") hata_raporu=$(q "select count(*) from client_error_reports") (hepsi 0 olmali)"
echo "   [036] users.deleted_at: $(q "select count(*) from information_schema.columns where table_name='users' and column_name='deleted_at'") (1 olmali); silinmis hesap: $(q "select count(*) from users where deleted_at is not null") (0 olmali)"
echo "   [036] CHECK chk_users_deleted_inactive: $(q "select count(*) from pg_constraint where conname='chk_users_deleted_inactive'") (1 olmali); account_data_exports: $(q "select count(*) from information_schema.tables where table_name='account_data_exports'") (1 olmali)"
echo "   [036] kismi indeksler (audit_log/door_access_logs): $(q "select count(*) from pg_indexes where tablename in ('audit_log','door_access_logs') and indexdef like '%WHERE%' and (indexname like '%actor%' or indexname like '%user%')") (bilgi)"
echo "   [038] bulk_import_runs: tablo=$(q "select count(*) from information_schema.tables where table_schema='public' and table_name='bulk_import_runs'") (1 olmali) FK=$(q "select count(*) from pg_constraint where conrelid='bulk_import_runs'::regclass and conname in ('fk_bulk_import_runs_site','fk_bulk_import_runs_created_by')") (2 olmali) indeks=$(q "select count(*) from pg_indexes where tablename='bulk_import_runs' and indexname in ('uq_bulk_import_runs_key','idx_bulk_import_runs_site','idx_bulk_import_runs_created_by')") (3 olmali) satir=$(q "select count(*) from bulk_import_runs") (0 olmali)"
echo "   [039] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('documents','document_versions','announcement_attachments')") (3 olmali); kisit=$(q "select count(*) from pg_constraint where conname in ('chk_documents_status','chk_document_versions_status','uq_document_versions_key','chk_document_versions_ready')") (4 olmali); indeks=$(q "select count(*) from pg_indexes where indexname in ('idx_documents_site_status','uq_documents_idempotency','idx_document_versions_site')") (3 olmali)"
echo "   [039] satirlar: belge=$(q "select count(*) from documents") surum=$(q "select count(*) from document_versions") ek=$(q "select count(*) from announcement_attachments") (hepsi 0 olmali); eski belge modulu satiri once/sonra: $before_doc_sm/$after_doc_sm (esit olmali; 084 silmez, katalog yok sayar)"
echo "   [040] tablolar: $(q "select count(*) from information_schema.tables where table_schema='public' and table_name in ('finance_settings','late_fee_runs','late_fee_run_lines','receipt_counters','receipts','receipt_print_events','finance_accounts','expense_categories','finance_suppliers','expenses','expense_voids','expense_documents','account_movements','account_transfers','account_reconciliations','finance_reminder_runs','finance_reminder_items','finance_reminder_apartments','finance_reminder_exclusions')") (19 olmali); tetikleyici: $(q "select count(*) from pg_trigger where not tgisinternal and tgname in ('trg_account_movements_check','trg_account_movements_immutable','trg_account_movements_no_truncate','trg_account_reconciliations_immutable','trg_account_reconciliations_no_truncate','trg_account_transfers_immutable','trg_account_transfers_no_truncate','trg_expense_documents_guard','trg_expense_documents_no_truncate','trg_expense_voids_immutable','trg_expense_voids_no_truncate','trg_expenses_immutable','trg_expenses_no_truncate','trg_finance_accounts_guard','trg_finance_reminder_runs_guard','trg_finance_settings_guard','trg_late_fee_run_lines_check','trg_late_fee_run_lines_immutable','trg_late_fee_run_lines_no_truncate','trg_late_fee_runs_chain','trg_late_fee_runs_guard','trg_late_fee_runs_no_truncate','trg_ledger_entries_late_fee_mirror','trg_receipt_counters_guard','trg_receipt_counters_no_truncate','trg_receipt_print_events_immutable','trg_receipt_print_events_no_truncate','trg_receipts_immutable','trg_receipts_insert_check','trg_receipts_no_truncate')") (30 olmali)"
echo "   [040] ledger_entries.late_fee_run_id: $(q "select count(*) from information_schema.columns where table_name='ledger_entries' and column_name='late_fee_run_id'") (1 olmali); notification_preferences.email_finance_reminders: $(q "select count(*) from information_schema.columns where table_name='notification_preferences' and column_name='email_finance_reminders'") (1 olmali); kisit: $(q "select count(*) from pg_constraint where conname in ('chk_ledger_entries_late_fee','fk_ledger_entries_late_fee_run')") (2 olmali)"
echo "   [040] satirlar: gecikme_faizi=$(q "select count(*) from late_fee_runs") makbuz=$(q "select count(*) from receipts") gider=$(q "select count(*) from expenses") hesap=$(q "select count(*) from finance_accounts") hatirlatma=$(q "select count(*) from finance_reminder_runs") (hepsi 0 olmali)"
echo "   [041] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('push_devices','push_outbox')") (2 olmali); notification_preferences push sutunlari: $(q "select count(*) from information_schema.columns where table_name='notification_preferences' and column_name in ('push_show_preview','push_quiet_enabled','push_quiet_start','push_quiet_end')") (4 olmali); kisit: $(q "select count(*) from pg_constraint where conname='chk_notification_preferences_push_quiet'") (1 olmali); indeks: $(q "select count(*) from pg_indexes where indexname in ('uq_push_devices_token','idx_push_outbox_pending')") (2 olmali)"
echo "   [041] satirlar: cihaz=$(q "select count(*) from push_devices") kuyruk=$(q "select count(*) from push_outbox") (hepsi 0 olmali)"
echo "   [044-046] tablolar: $(q "select string_agg(table_name, ',' order by table_name) from information_schema.tables where table_schema='public' and table_name in ('surveys','survey_votes','visitor_entries','access_cards')") (4 olmali); satirlar: anket=$(q "select count(*) from surveys") oy=$(q "select count(*) from survey_votes") ziyaretci=$(q "select count(*) from visitor_entries") kart=$(q "select count(*) from access_cards") (hepsi 0 olmali); yeni secmeli modul ACIK site (0 olmali; survey 082'den beri TEMEL modul, her sitede acik olur: ok082): $(q "select count(*) from site_modules where module_code in ('visitor_log','card_access') and enabled")"
echo "   [047-048] fotograf tablosu: $(q "select count(*) from information_schema.tables where table_schema='public' and table_name='work_item_attachments'") (1 olmali), satir=$(q "select count(*) from work_item_attachments") (0 olmali); olay turu kisiti foto: $(q "select count(*) from pg_constraint where conname='chk_work_item_events_type' and pg_get_constraintdef(oid) like '%attachment_added%'") (1 olmali); okunmamis kolonlari: $(q "select count(*) from information_schema.columns where table_name in ('reservations','concierge_requests') and column_name in ('resident_updated_at','resident_seen_at')") (4 olmali); okunmamis gorunen kayit: rez=$(q "select count(*) from reservations where resident_updated_at > resident_seen_at") konsiyerj=$(q "select count(*) from concierge_requests where resident_updated_at > resident_seen_at") (bilgi: yalniz 048 ilk kez kurulurken 0 olmali)"
