echo "   [yasal] pakette legal/*.md: $(ls "$STAGE/legal" 2>/dev/null | wc -l) dosya (5 olmali)"
# NOT: NODE_ENV=production iken sunucu SERVER_SKIP_START'i YOK SAYAR ve normal baslar (kasitli guvenlik); bu yuzden burada NODE_ENV=test.
echo "   [modul yukleme] yeni kod ice aktarma (ag/DB yok): $(cd "$STAGE" && SERVER_SKIP_START=1 NODE_ENV=test JWT_SECRET="$(openssl rand -hex 40)" timeout 60 node --input-type=module -e "await import('./src/server.js'); console.log('IMPORT_OK'); process.exit(0)" 2>&1 | tail -n 1 | cut -c1-120)"
echo "   site_memberships CHECK: $($PSQL -d "$RDB" -Atc "select string_agg(conname, ',') from pg_constraint where conrelid='site_memberships'::regclass and contype='c'")"
